// Ein geworfener Fehler im Renderer landet sonst nur in der DevTools-Konsole,
// die kein Nutzer je oeffnet: fuer ihn ist der Launcher einfach "kaputt" und
// niemand erfaehrt davon. Muss ganz oben stehen, damit auch Fehler aus dem
// restlichen Aufbau dieser Datei noch erfasst werden.
// Kein Inline-Handler (onerror="..."), das verbietet die CSP.
(function absturzHakenOberflaeche() {
  var gemeldeteFehler = Object.create(null);
  function melde(schluesselArt, meldung, spur) {
    try {
      var text = String(meldung || "").slice(0, 500);
      var stapel = String(spur || "").slice(0, 4000);
      // Jede identische Meldung nur einmal pro Programmlauf: ein Fehler in
      // einer Schleife (Render-Tick, Intervall) wuerde den Server sonst
      // mit tausenden gleichen Berichten zumuellen.
      var schluessel = schluesselArt + "|" + text + "|" + stapel.split("\n")[0];
      if (gemeldeteFehler[schluessel]) {
        return;
      }
      gemeldeteFehler[schluessel] = true;
      if (window.viscode && typeof window.viscode.meldeFehler === "function") {
        window.viscode.meldeFehler({
          meldung: text,
          spur: stapel
        });
      }
    } catch (_ignoriert) {}
  }
  window.addEventListener("error", function (ereignis) {
    try {
      // Fehlgeschlagene Bilder/Medien feuern dasselbe Ereignis, haben aber ein
      // Element als target. Die sind Alltag (tote Cover-URLs) und kein Absturz
      // - ohne diese Weiche wuerde jedes kaputte Titelbild gemeldet.
      if (ereignis && ereignis.target && ereignis.target !== window) {
        return;
      }
      var fehler = ereignis && ereignis.error;
      var ort = "";
      if (ereignis && ereignis.filename) {
        ort = ereignis.filename + ":" + (ereignis.lineno || 0) + ":" + (ereignis.colno || 0);
      }
      melde("fehler", fehler && fehler.message || ereignis && ereignis.message || "Unbekannter Fehler", fehler && fehler.stack || ort);
    } catch (_ignoriert) {}
  });
  window.addEventListener("unhandledrejection", function (ereignis) {
    try {
      var grund = ereignis && ereignis.reason;
      melde("promise", "Promise-Fehler: " + (grund && grund.message || String(grund)), grund && grund.stack || "");
    } catch (_ignoriert) {}
  });
})();

