    ov.innerHTML = "\n      <div class=\"ask-box\">\n        <h3>" + titel + "</h3>\n        <p style=\"font-size:13.5px;line-height:1.6;color:var(--text-faint,#c7ccd6);margin:0 0 6px\">" + text + "</p>\n        <div class=\"ask-actions\">\n          <button class=\"btn-ghost\" data-act=\"details\" style=\"margin-right:auto\">ðŸ“‹ Details / Was passiert mit meinen Daten?</button>\n          <button class=\"btn-ghost\" data-act=\"cancel\">Abbrechen</button>\n          <button class=\"btn-primary\" data-act=\"ok\">" + okLabel + "</button>\n        </div>\n      </div>";
    document.body.appendChild(ov);
