// Steam/Epic/Xbox sind immer an (null), EA/Ubisoft/GOG haben einen Schalter.
const VYSTRA_NATIVE_LAUNCHER = { steam: null, epic: null, xbox: null, ea: "connectEA", ubisoft: "connectUbisoft", gog: "connectGOG" };
// Plattformen, deren Schalter dem Login-Flow gehoert (oauth:true in den
// Plattform-Definitionen): wird erst nach erfolgreicher Anmeldung gesetzt.
const VYSTRA_OAUTH_LAUNCHER = new Set(["gog", "ubisoft", "xbox"]);
