function openCreateTeamDialog() {
  return new Promise(resolve => {
    const old = document.getElementById("teamCreateOverlay");
    if (old) old.remove();
    const ov = document.createElement("div");
    ov.id = "teamCreateOverlay";
    ov.className = "ask-overlay";
    ov.innerHTML = `
      <div class="ask-box teams-create-box">
        <h3>Team / Clan erstellen</h3>
        <div class="field"><label>Name</label><input type="text" class="ask-input tc-name" maxlength="40" placeholder="z. B. NachtwÃ¶lfe"></div>
        <div class="field"><label>Tag <span class="acc-opt">(max. 6, optional)</span></label><input type="text" class="ask-input tc-tag" maxlength="6" placeholder="z. B. NW"></div>
        <div class="field"><label>Typ</label><div class="tc-kind">
          <label class="tc-kopt"><input type="radio" name="tcKind" value="clan" checked> ðŸ° Clan</label>
          <label class="tc-kopt"><input type="radio" name="tcKind" value="team"> ðŸ›¡ï¸ Team</label>
        </div></div>
        <div class="wl-form-err" hidden></div>
        <div class="ask-actions"><button class="btn-ghost tc-cancel">Abbrechen</button><button class="btn-primary tc-ok">Erstellen</button></div>
      </div>`;
    document.body.appendChild(ov);
    const nameEl = ov.querySelector(".tc-name");
    const tagEl = ov.querySelector(".tc-tag");
    const errEl = ov.querySelector(".wl-form-err");
    nameEl.focus();
    let done = false;
    const finish = v => { if (done) return; done = true; ov.remove(); resolve(v); };
    const submit = async () => {
      const n = nameEl.value.trim();
      const tg = tagEl.value.trim();
      const kindEl = ov.querySelector("input[name=\"tcKind\"]:checked");
      const kind = kindEl ? kindEl.value : "clan";
      if (!n) { errEl.textContent = "Bitte einen Namen eingeben."; errEl.hidden = false; return; }
      const okBtn = ov.querySelector(".tc-ok");
      okBtn.disabled = true; okBtn.textContent = "Erstelle â€¦";
      const bodyObj = { kind: kind, name: n };
      if (tg) bodyObj.tag = tg;
      let r = null;
      try { r = await api.socialApi("POST", "/removed", bodyObj); } catch { r = null; }
      if (r && r.ok) { toast("â€ž" + n + "\" erstellt ðŸŽ‰"); finish(true); }
      else { okBtn.disabled = false; okBtn.textContent = "Erstellen"; errEl.textContent = _teamErr(r, "Konnte nicht erstellt werden."); errEl.hidden = false; }
    };
    ov.querySelector(".tc-ok").addEventListener("click", submit);
    ov.querySelector(".tc-cancel").addEventListener("click", () => finish(false));
    ov.addEventListener("click", e => { if (e.target === ov) finish(false); });
    ov.addEventListener("keydown", e => {
      if (e.key === "Escape") finish(false);
      else if (e.key === "Enter") submit();
    });
  });
}
