async function inviteFriendToTeamMenu(friend, anchor) {
  // Spiel-Einladung geht als Chat-Nachricht + Deep-Link an ein Konto.
  if (gastGesperrt("inviteFriendToTeamMenu")) {
    return;
  }
  const username = friend && friend.username;
  if (!username) { toast("Nur Vystra-Nutzer mit Benutzernamen kÃ¶nnen eingeladen werden."); return; }
  const oldMenu = document.getElementById("teamInvMenu");
  if (oldMenu) oldMenu.remove();
  let r = null;
  try { r = await api.socialApi("GET", "/removed"); } catch { r = null; }
  const teams = _teamsListFrom(r && r.ok && r.data, ["teams", "items", "data"]).filter(t => {
    const role = String(t.myRole || t.role || "member").toLowerCase();
    return role === "owner" || role === "admin";
  });
  if (!teams.length) { toast("Du hast keinen Clan/Team, in den du einladen darfst."); return; }
  const menu = document.createElement("div");
  menu.id = "teamInvMenu";
  menu.className = "teams-mini-menu";
  menu.innerHTML = `<div class="teams-mini-t">â€ž` + esc(friend.name || username) + `" einladen zu:</div>` + teams.map(t => `<button class="teams-mini-item" data-team="` + esc(String(t.id != null ? t.id : "")) + `">` + (t.kind === "clan" ? "ðŸ°" : "ðŸ›¡ï¸") + ` ` + (t.tag ? `[` + esc(String(t.tag)) + `] ` : "") + esc(t.name || "Team") + `</button>`).join("");
  document.body.appendChild(menu);
  try {
    const rect = anchor.getBoundingClientRect();
    menu.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - 260)) + "px";
    menu.style.top = (rect.bottom + 6) + "px";
  } catch {}
  const closeMenu = e => { if (!menu.contains(e.target)) { menu.remove(); document.removeEventListener("mousedown", closeMenu); } };
  setTimeout(() => document.addEventListener("mousedown", closeMenu), 0);
  menu.querySelectorAll("[data-team]").forEach(b => b.addEventListener("click", async () => {
    menu.remove();
    document.removeEventListener("mousedown", closeMenu);
    let ir = null;
    try { ir = await api.socialApi("POST", "/removed/" + encodeURIComponent(b.dataset.team) + "/invite", { username: username }); } catch { ir = null; }
    if (ir && ir.ok) toast("â€ž" + username + "\" eingeladen âœ“");
    else toast(_teamErr(ir, "Einladung fehlgeschlagen."));
  }));
}

/* ============================================================================
   VYSTRA-ANRUFE (Audio / Video / Screenshare) via WebRTC
   - Signaling ueber den generischen P2P-Server (wss://removed.invalid)
   - Anruf-Einladung + Ablehnung laufen ueber den bestehenden Chat
   ========================================================================== */
const VC_CALL_PREFIX = "[[vystra-call]]";
const VC_CALL_DECLINE_PREFIX = "[[vystra-call-decline]]";
const VC_SIGNALING_URL = "wss://removed.invalid";
const VC_TITLE_ID = "vystra-call";

function vcParseCall(text) {
  if (typeof text !== "string") return null;
  let kind = null, rest = null;
  if (text.indexOf(VC_CALL_DECLINE_PREFIX) === 0) {
    kind = "decline";
    rest = text.slice(VC_CALL_DECLINE_PREFIX.length);
  } else if (text.indexOf(VC_CALL_PREFIX) === 0) {
    kind = "call";
    rest = text.slice(VC_CALL_PREFIX.length);
  } else {
    return null;
  }
  let data = {};
  try { data = JSON.parse(rest) || {}; } catch { data = {}; }
  return { kind, data };
}

// Aus einer Chat-Nachricht eine System-Zeile machen (statt Roh-JSON im Chat).
function vcCallNote(msg) {
  if (!msg || msg.deleted) return null;
  const parsed = vcParseCall(msg.text);
  if (!parsed) return null;
  const mine = msg.from === "me";
  let icon, label;
  if (parsed.kind === "decline") {
    icon = "ðŸ“ž";
    label = "Anruf abgelehnt";
  } else {
    const isVideo = parsed.data && parsed.data.type === "video";
    icon = isVideo ? "ðŸ“¹" : "ðŸ“ž";
    label = (mine ? "Ausgehender " : "Eingehender ") + (isVideo ? "Videoanruf" : "Sprachanruf");
  }
  let time = "";
  try { time = new Date(msg.ts).toLocaleTimeString("de-DE", { hour: "2-digit", minute: "2-digit" }); } catch {}
  return "\n    <div class=\"chat-call-note\"><span class=\"ccn-ico\">" + icon + "</span><span class=\"ccn-label\">" + esc(label) + "</span>" + (time ? "<span class=\"ccn-time\">" + esc(time) + "</span>" : "") + "</div>";
}

const VystraCall = {
  state: "idle", // idle | starting | outgoing | incoming | connecting | active
  friend: null,
  callType: "audio",
  isCaller: false,
  polite: false,
  ws: null,
  pc: null,
  localStream: null,
  remoteStream: null,
  cameraTrack: null,
  screenStream: null,
  screenTrack: null,
  gameId: null,
  joinCode: null,
  myPeerId: null,
  remotePeerId: null,
  _muted: false,
  _camOff: false,
  _screenOn: false,
  _makingOffer: false,
  _ignoreOffer: false,
  _closing: false,
  _pendingSignals: [],
  _handledCallIds: new Set(),
  _prevPreview: {},

  // ICE-Server (TURN aus Settings + Google-STUN)
  async _iceServers() {
    let s = (state && state.settings) || {};
    try { if (!s.turnUrl) s = (await api.getSettings()) || s; } catch {}
    const servers = [{ urls: "stun:stun.l.google.com:19302" }];
    if (s.turnUrl) {
      servers.push({ urls: s.turnUrl, username: s.turnUsername || "", credential: s.turnCredential || "" });
    }
    return servers;
  },

  // Anruf STARTEN (Anrufer)
  async startCall(friend, type) {
    if (this.state !== "idle") { toast("Es lÃ¤uft bereits ein Anruf."); return; }
    if (!friend || !friend.id) { toast("Freund nicht gefunden."); return; }
    type = type === "video" ? "video" : "audio";
    this.state = "starting";
    this.friend = { id: friend.id, name: friend.name || friend.username, username: friend.username };
    this.callType = type;
    this.isCaller = true;
    this.polite = false;
    try {
      this.localStream = await navigator.mediaDevices.getUserMedia({
        audio: true,
        video: type === "video" ? { width: { ideal: 1280 }, height: { ideal: 720 } } : false
      });
    } catch (e) {
      toast(type === "video" ? "Kamera/Mikro nicht verfÃ¼gbar." : "Mikrofon nicht verfÃ¼gbar.");
      this._reset();
      return;
    }
    if (type === "video") this.cameraTrack = this.localStream.getVideoTracks()[0] || null;
    this.state = "outgoing";
    this._showCallWindow();
    this._setStatus("Verbinden â€¦");
    this._attachLocal();
    this._connect("host");
  },

  // Eingehenden Anruf annehmen
  async accept() {
    if (this.state !== "incoming") return;
    this._stopRing();
    if (this._incomingTimeout) { clearTimeout(this._incomingTimeout); this._incomingTimeout = null; }
    const type = this.callType;
    try {
      this.localStream = await navigator.mediaDevices.getUserMedia({
        audio: true,
        video: type === "video" ? { width: { ideal: 1280 }, height: { ideal: 720 } } : false
      });
    } catch (e) {
      toast(type === "video" ? "Kamera/Mikro nicht verfÃ¼gbar." : "Mikrofon nicht verfÃ¼gbar.");
      this.decline();
      return;
    }
    if (type === "video") this.cameraTrack = this.localStream.getVideoTracks()[0] || null;
    this.isCaller = false;
    this.polite = true;
    try { if (this.friend) ChatStore.markRead(this.friend.id); } catch {}
    this._removeIncomingUI();
    this.state = "connecting";
    this._showCallWindow();
    this._setStatus("Verbinden â€¦");
    this._attachLocal();
    this._connect("guest");
  },

  // Eingehenden Anruf ablehnen
  decline() {
    if (this.state !== "incoming") return;
    this._stopRing();
    if (this._incomingTimeout) { clearTimeout(this._incomingTimeout); this._incomingTimeout = null; }
    try { if (this.friend) ChatStore.send(this.friend.id, VC_CALL_DECLINE_PREFIX + JSON.stringify({ ts: Date.now() })); } catch {}
    try { if (this.friend) ChatStore.markRead(this.friend.id); } catch {}
    this._removeIncomingUI();
    this._reset();
  },

  // Auflegen
  hangup() {
    if (this.state === "idle") return;
    this._reset();
  },

  // Interner Empfang eines eingehenden Anrufs (vom Chat-Poll ausgeloest)
  _onIncoming(friend, data) {
    if (this.state !== "idle") {
      try { ChatStore.send(friend.id, VC_CALL_DECLINE_PREFIX + JSON.stringify({ ts: Date.now(), busy: true })); } catch {}
      return;
    }
    this.friend = { id: friend.id, name: friend.nickname || friend.name || friend.username, username: friend.username };
    this.callType = data && data.type === "video" ? "video" : "audio";
    this.joinCode = data && data.code;
    if (!this.joinCode) { this.friend = null; return; }
    this.isCaller = false;
    this.state = "incoming";
    this._showIncomingUI(this.friend, this.callType);
    this._startRing();
    this._incomingTimeout = setTimeout(() => { if (this.state === "incoming") this.decline(); }, 45000);
  },

  // WebSocket-Signaling
  _connect(role) {
    let ws;
    try { ws = new WebSocket(VC_SIGNALING_URL); } catch (e) {
      toast("Anruf-Server nicht erreichbar.");
      this._reset();
      return;
    }
    this.ws = ws;
    this._wsConnectTimeout = setTimeout(() => {
      if (ws.readyState !== 1) { toast("Anruf-Server nicht erreichbar."); this._reset(); }
    }, 10000);
    ws.onopen = () => {
      if (this._wsConnectTimeout) { clearTimeout(this._wsConnectTimeout); this._wsConnectTimeout = null; }
      if (role === "host") this._wsSend({ typ: "erstellen", titleId: VC_TITLE_ID, maxSpieler: 2, sichtbar: false });
      else this._wsSend({ typ: "joinen", titleId: VC_TITLE_ID, code: this.joinCode });
      this._pingTimer = setInterval(() => this._wsSend({ typ: "ping" }), 25000);
    };
    ws.onmessage = ev => {
      let m; try { m = JSON.parse(typeof ev.data === "string" ? ev.data : ""); } catch { return; }
      if (m) this._onWsMessage(m);
    };
    ws.onerror = () => {};
    ws.onclose = () => {
      if (!this._closing && this.state !== "idle") {
        toast("Anruf-Verbindung getrennt.");
        this._reset();
      }
    };
  },

  _wsSend(obj) {
    try { if (this.ws && this.ws.readyState === 1) this.ws.send(JSON.stringify(obj)); } catch {}
  },

  _onWsMessage(m) {
    switch (m.typ) {
      case "erstellt":
        this.gameId = m.gameId;
        this.joinCode = m.joinCode;
        this.myPeerId = m.deineId;
        this._sendInvite();
        break;
      case "gejoint":
        this.myPeerId = m.deineId;
        this.remotePeerId = m.hostId;
        this._stopRing();
        this._createPeer();
        break;
      case "spieler-joint":
        if (this.isCaller && m.id) {
          this.remotePeerId = m.id;
          this._stopRingback();
          this._setStatus("Verbinden â€¦");
          this._createPeer();
        }
        break;
      case "signal":
        this._onSignal(m.von, m.daten);
        break;
      case "spieler-weg":
        if (this.state !== "idle") { toast("Anruf beendet."); this._reset(); }
        break;
      case "game-zu":
        if (this.state !== "idle") { toast("Anruf beendet."); this._reset(); }
        break;
      case "ping":
        this._wsSend({ typ: "pong" });
        break;
      case "pong":
        break;
      case "fehler":
      case "error":
        toast("Anruf fehlgeschlagen: " + (m.grund || m.error || "unbekannt"));
        this._reset();
        break;
      default:
        break;
    }
  },

  _sendInvite() {
    const u = (state.settings && state.settings.user) || {};
    const payload = {
      code: this.joinCode,
      type: this.callType,
      from: u.username || "",
      name: u.displayName || u.username || "Freund",
      ts: Date.now()
    };
    try { ChatStore.send(this.friend.id, VC_CALL_PREFIX + JSON.stringify(payload)); } catch {}
    this._setStatus("Ruft an â€¦");
    this._startRingback();
    this._outgoingTimeout = setTimeout(() => {
      if (this.state === "outgoing") { toast("Keine Antwort."); this._reset(); }
    }, 45000);
  },

  // RTCPeerConnection (Perfect Negotiation)
  async _createPeer() {
    if (this.pc) return;
    if (this.state === "outgoing" || this.state === "connecting") this.state = "connecting";
    let servers;
    try { servers = await this._iceServers(); } catch { servers = [{ urls: "stun:stun.l.google.com:19302" }]; }
    let pc;
    try { pc = new RTCPeerConnection({ iceServers: servers }); } catch (e) {
      toast("WebRTC nicht verfÃ¼gbar.");
      this._reset();
      return;
    }
    this.pc = pc;
    this._makingOffer = false;
    this._ignoreOffer = false;
    if (this.localStream) {
      this.localStream.getTracks().forEach(t => { try { pc.addTrack(t, this.localStream); } catch {} });
    }
    pc.onnegotiationneeded = async () => {
      try {
        this._makingOffer = true;
        await pc.setLocalDescription();
        this._wsSend({ typ: "signal", an: this.remotePeerId, daten: { sdp: pc.localDescription } });
      } catch (e) {} finally {
        this._makingOffer = false;
      }
    };
    pc.onicecandidate = ev => {
      if (ev.candidate) this._wsSend({ typ: "signal", an: this.remotePeerId, daten: { ice: ev.candidate } });
    };
    pc.ontrack = ev => {
      this.remoteStream = (ev.streams && ev.streams[0]) || this.remoteStream || new MediaStream([ev.track]);
      this._attachRemote();
    };
    pc.onconnectionstatechange = () => {
      const st = pc.connectionState;
      if (st === "connected") {
        this.state = "active";
        if (this._graceTimer) { clearTimeout(this._graceTimer); this._graceTimer = null; }
        if (this._outgoingTimeout) { clearTimeout(this._outgoingTimeout); this._outgoingTimeout = null; }
        this._stopRing();
        this._stopRingback();
        this._setStatus("");
        this._attachRemote();
        this._updateControls();
      } else if (st === "failed") {
        if (this.state !== "idle") { toast("Verbindung fehlgeschlagen."); this._reset(); }
      } else if (st === "closed") {
        if (this.state !== "idle") this._reset();
      } else if (st === "disconnected") {
        if (this._graceTimer) clearTimeout(this._graceTimer);
        this._graceTimer = setTimeout(() => {
          if (this.pc && (this.pc.connectionState === "disconnected" || this.pc.connectionState === "failed")) {
            toast("Anruf beendet.");
            this._reset();
          }
        }, 10000);
      }
    };
    if (this._pendingSignals && this._pendingSignals.length) {
      const q = this._pendingSignals.slice();
      this._pendingSignals = [];
      for (const s of q) this._onSignal(s.von, s.daten);
    }
  },

  async _onSignal(von, daten) {
    if (!daten) return;
    if (!this.pc) { (this._pendingSignals = this._pendingSignals || []).push({ von, daten }); return; }
    const pc = this.pc;
    try {
      if (daten.sdp) {
        const desc = daten.sdp;
        const offerCollision = desc.type === "offer" && (this._makingOffer || pc.signalingState !== "stable");
        this._ignoreOffer = !this.polite && offerCollision;
        if (this._ignoreOffer) return;
        await pc.setRemoteDescription(desc);
        if (desc.type === "offer") {
          await pc.setLocalDescription();
          this._wsSend({ typ: "signal", an: this.remotePeerId, daten: { sdp: pc.localDescription } });
        }
      } else if (daten.ice) {
        try { await pc.addIceCandidate(daten.ice); } catch (e) { if (!this._ignoreOffer) {} }
      }
    } catch (e) {}
  },

  // Steuerung: Mute / Kamera / Screenshare
  toggleMute() {
    if (!this.localStream) return;
    const a = this.localStream.getAudioTracks()[0];
    if (!a) return;
    a.enabled = !a.enabled;
    this._muted = !a.enabled;
    this._updateControls();
  },

  toggleCam() {
    if (this.callType !== "video" || !this.cameraTrack) { toast("Kein Kamerabild in diesem Anruf."); return; }
    if (this._screenOn) { toast("Beende zuerst die Bildschirmfreigabe."); return; }
    this.cameraTrack.enabled = !this.cameraTrack.enabled;
    this._camOff = !this.cameraTrack.enabled;
    this._updateControls();
    this._attachLocal();
  },

  async toggleScreen() {
    if (!this.pc || (this.state !== "active" && this.state !== "connecting")) { return; }
    if (this._screenOn) { await this._stopScreen(); return; }
    let stream;
    try { stream = await navigator.mediaDevices.getDisplayMedia({ video: true, audio: false }); }
    catch (e) { if (e && e.name !== "NotAllowedError") toast("Bildschirmfreigabe nicht mÃ¶glich."); return; }
    const track = stream.getVideoTracks()[0];
    if (!track) { try { stream.getTracks().forEach(t => t.stop()); } catch {} return; }
    this.screenStream = stream;
    this.screenTrack = track;
    let vsender = this.pc.getSenders().find(s => s.track && s.track.kind === "video");
    if (!vsender) vsender = this.pc.getSenders().find(s => !s.track);
    try {
      if (vsender && vsender.replaceTrack) await vsender.replaceTrack(track);
      else this.pc.addTrack(track, stream);
    } catch (e) {
      try { this.pc.addTrack(track, stream); } catch {}
    }
    this._screenOn = true;
    track.onended = () => { this._stopScreen(); };
    this._attachLocal();
    this._updateControls();
  },

  async _stopScreen() {
    if (!this._screenOn) return;
    this._screenOn = false;
    try { if (this.screenTrack) this.screenTrack.stop(); } catch {}
    try { if (this.screenStream) this.screenStream.getTracks().forEach(t => t.stop()); } catch {}
    if (this.pc) {
      const vsender = this.pc.getSenders().find(s => s.track && s.track.kind === "video");
      if (vsender && vsender.replaceTrack) {
        try {
          if (this.callType === "video" && this.cameraTrack) await vsender.replaceTrack(this.cameraTrack);
          else await vsender.replaceTrack(null);
        } catch {}
      }
    }
    this.screenStream = null;
    this.screenTrack = null;
    this._attachLocal();
    this._updateControls();
  },

  // Aufraeumen
  _reset() {
    this._closing = true;
    try { if (this._pingTimer) clearInterval(this._pingTimer); } catch {}
    this._pingTimer = null;
    try { if (this._wsConnectTimeout) clearTimeout(this._wsConnectTimeout); } catch {}
    try { if (this._outgoingTimeout) clearTimeout(this._outgoingTimeout); } catch {}
    try { if (this._incomingTimeout) clearTimeout(this._incomingTimeout); } catch {}
    try { if (this._graceTimer) clearTimeout(this._graceTimer); } catch {}
    this._wsConnectTimeout = this._outgoingTimeout = this._incomingTimeout = this._graceTimer = null;
    this._stopRing();
    this._stopRingback();
    if (this.pc) {
      try {
        this.pc.ontrack = null; this.pc.onicecandidate = null;
        this.pc.onnegotiationneeded = null; this.pc.onconnectionstatechange = null;
        this.pc.close();
      } catch {}
      this.pc = null;
    }
    if (this.localStream) { try { this.localStream.getTracks().forEach(t => t.stop()); } catch {} this.localStream = null; }
    if (this.screenTrack) { try { this.screenTrack.stop(); } catch {} }
    if (this.screenStream) { try { this.screenStream.getTracks().forEach(t => t.stop()); } catch {} }
    this.remoteStream = null;
    this.screenTrack = null;
    this.screenStream = null;
    if (this.ws) {
      try {
        this.ws.onopen = this.ws.onmessage = this.ws.onerror = this.ws.onclose = null;
        this.ws.close();
      } catch {}
      this.ws = null;
    }
    this._removeCallWindow();
    this._removeIncomingUI();
    this.state = "idle";
    this.friend = null;
    this.remotePeerId = null;
    this.myPeerId = null;
    this.gameId = null;
    this.joinCode = null;
    this.isCaller = false;
    this.polite = false;
    this.cameraTrack = null;
    this._screenOn = false;
    this._muted = false;
    this._camOff = false;
    this._makingOffer = false;
    this._ignoreOffer = false;
    this._pendingSignals = [];
    this._closing = false;
  },

  // Oberflaeche: In-Call-Fenster
  _showCallWindow() {
    this._removeCallWindow();
    const f = this.friend || {};
    const name = esc(f.name || f.username || "Freund");
    const initial = esc(((f.name || f.username || "?")[0] || "?").toUpperCase());
    const el = document.createElement("div");
    el.id = "vcWindow";
    el.className = "vc-window";
    el.innerHTML = "\n      <div class=\"vc-remote-wrap\">\n        <video id=\"vcRemoteVideo\" class=\"vc-remote-video\" autoplay playsinline></video>\n        <div class=\"vc-remote-avatar\" id=\"vcRemoteAvatar\"><div class=\"vc-av-big df-av\">" + initial + "</div><div class=\"vc-remote-name\">" + name + "</div></div>\n        <div class=\"vc-status\" id=\"vcStatus\">Verbinden â€¦</div>\n        <div class=\"vc-local-pip\" id=\"vcLocalPip\"><video id=\"vcLocalVideo\" class=\"vc-local-video\" autoplay playsinline muted></video></div>\n      </div>\n      <div class=\"vc-controls\">\n        <button class=\"vc-ctrl\" id=\"vcBtnMute\" title=\"Mikrofon\">ðŸŽ¤</button>\n        <button class=\"vc-ctrl\" id=\"vcBtnCam\" title=\"Kamera\">ðŸ“·</button>\n        <button class=\"vc-ctrl\" id=\"vcBtnScreen\" title=\"Bildschirm teilen\">ðŸ–¥ï¸</button>\n        <button class=\"vc-ctrl vc-hangup\" id=\"vcBtnHangup\" title=\"Auflegen\">ðŸ“ž</button>\n      </div>";
    document.body.appendChild(el);
    const mb = el.querySelector("#vcBtnMute");
    const cb = el.querySelector("#vcBtnCam");
    const sb = el.querySelector("#vcBtnScreen");
    const hb = el.querySelector("#vcBtnHangup");
    if (mb) mb.addEventListener("click", () => this.toggleMute());
    if (cb) cb.addEventListener("click", () => this.toggleCam());
    if (sb) sb.addEventListener("click", () => this.toggleScreen());
    if (hb) hb.addEventListener("click", () => { toast("Anruf beendet."); this.hangup(); });
    this._updateControls();
    this._attachLocal();
    this._attachRemote();
  },

  _removeCallWindow() {
    const el = document.getElementById("vcWindow");
    if (el) el.remove();
  },

  _updateControls() {
    const el = document.getElementById("vcWindow");
    if (!el) return;
    const mute = el.querySelector("#vcBtnMute");
    const cam = el.querySelector("#vcBtnCam");
    const scr = el.querySelector("#vcBtnScreen");
    if (mute) {
      mute.classList.toggle("vc-off", !!this._muted);
      mute.textContent = this._muted ? "ðŸ”‡" : "ðŸŽ¤";
      mute.title = this._muted ? "Mikro einschalten" : "Mikro stumm";
    }
    if (cam) {
      if (this.callType !== "video") {
        cam.style.display = "none";
      } else {
        cam.style.display = "";
        cam.classList.toggle("vc-off", !!this._camOff);
        cam.textContent = this._camOff ? "ðŸš«" : "ðŸ“·";
        cam.title = this._camOff ? "Kamera einschalten" : "Kamera aus";
      }
    }
    if (scr) {
      scr.classList.toggle("vc-active", !!this._screenOn);
      scr.title = this._screenOn ? "Bildschirmfreigabe beenden" : "Bildschirm teilen";
    }
  },

  _setStatus(t) {
    const s = document.getElementById("vcStatus");
    // Klingel-/Verbindungs-Ring am Anrufer-Avatar: pulsiert solange ein Status (Ruft an â€¦ / Verbinden â€¦) anliegt, aus sobald verbunden ("").
    try {
      const avEl = document.querySelector("#vcRemoteAvatar .vc-av-big");
      if (avEl) avEl.classList.toggle("call-ringing", !!t);
    } catch {}
    if (!s) return;
    if (t) { s.textContent = t; s.style.display = ""; }
    else { s.style.display = "none"; }
  },

  _attachLocal() {
    const v = document.getElementById("vcLocalVideo");
    const pip = document.getElementById("vcLocalPip");
    if (!v) return;
    let stream = null, show = false;
    if (this._screenOn && this.screenStream) { stream = this.screenStream; show = true; }
    else if (this.callType === "video" && this.localStream && this.cameraTrack && !this._camOff) { stream = this.localStream; show = true; }
    if (show && stream) {
      if (v.srcObject !== stream) v.srcObject = stream;
      if (v.play) v.play().catch(() => {});
      if (pip) pip.style.display = "";
    } else {
      v.srcObject = null;
      if (pip) pip.style.display = "none";
    }
  },

  _attachRemote() {
    const v = document.getElementById("vcRemoteVideo");
    const av = document.getElementById("vcRemoteAvatar");
    const hasVideo = !!(this.remoteStream && this.remoteStream.getVideoTracks().some(t => t.readyState === "live" && t.enabled));
    if (v) {
      if (this.remoteStream) {
        if (v.srcObject !== this.remoteStream) v.srcObject = this.remoteStream;
        if (v.play) v.play().catch(() => {});
      }
      v.style.display = hasVideo ? "" : "none";
    }
    if (av) av.style.display = hasVideo ? "none" : "";
  },

  // Oberflaeche: eingehender Anruf
  _showIncomingUI(friend, type) {
    this._removeIncomingUI();
    const name = esc(friend.name || friend.username || "Freund");
    const initial = esc(((friend.name || friend.username || "?")[0] || "?").toUpperCase());
    const label = type === "video" ? "ðŸ“¹ Eingehender Videoanruf" : "ðŸ“ž Eingehender Sprachanruf";
    const el = document.createElement("div");
    el.id = "vcIncoming";
    el.className = "vc-incoming";
    el.innerHTML = "\n      <div class=\"vc-incoming-card\">\n        <div class=\"vc-ring-pulse\"><div class=\"vc-av-big df-av call-ringing\">" + initial + "</div></div>\n        <div class=\"vc-incoming-name\">" + name + "</div>\n        <div class=\"vc-incoming-label\">" + label + "</div>\n        <div class=\"vc-incoming-actions\">\n          <button class=\"vc-in-btn vc-accept\" id=\"vcAccept\">ðŸ“ž Annehmen</button>\n          <button class=\"vc-in-btn vc-decline\" id=\"vcDecline\">âœ– Ablehnen</button>\n        </div>\n      </div>";
    document.body.appendChild(el);
    const ab = el.querySelector("#vcAccept");
    const db = el.querySelector("#vcDecline");
    if (ab) ab.addEventListener("click", () => this.accept());
    if (db) db.addEventListener("click", () => this.decline());
  },

  _removeIncomingUI() {
    const el = document.getElementById("vcIncoming");
    if (el) el.remove();
  },

  // Klingelton / Freizeichen (WebAudio)
  _ensureAudioCtx() {
    try {
      if (!this._audioCtx) this._audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      if (this._audioCtx.state === "suspended") this._audioCtx.resume();
    } catch {}
    return this._audioCtx;
  },
  _tone(freq, dur, vol, delay) {
    const ctx = this._ensureAudioCtx();
    if (!ctx) return;
    try {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = "sine";
      o.frequency.value = freq;
      o.connect(g); g.connect(ctx.destination);
      const t = ctx.currentTime + (delay || 0);
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(vol, t + 0.03);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.start(t);
      o.stop(t + dur + 0.05);
    } catch {}
  },
  _startRing() {
    this._stopRing();
    const ring = () => { this._tone(620, 0.32, 0.16, 0); this._tone(620, 0.32, 0.16, 0.42); };
    ring();
    this._ringTimer = setInterval(ring, 2200);
  },
  _stopRing() { if (this._ringTimer) { clearInterval(this._ringTimer); this._ringTimer = null; } },
  _startRingback() {
    this._stopRingback();
    const rb = () => { this._tone(440, 0.8, 0.07, 0); };
    rb();
    this._ringbackTimer = setInterval(rb, 3000);
  },
  _stopRingback() { if (this._ringbackTimer) { clearInterval(this._ringbackTimer); this._ringbackTimer = null; } },

  // Eingehende Anrufe erkennen (globaler Poll ueber den Chat)
  async _pollIncoming() {
    if (!state.settings || !state.settings.user) return;
    let res;
    try { res = await api.socialApi("GET", "/removed"); } catch { return; }
    const data = res && res.ok && res.data;
    if (!data || !Array.isArray(data.chats)) return;
    if (data.userId) ChatStore.db.myUserId = String(data.userId);
    for (const chat of data.chats) {
      const partner = chat.partner || chat.user || (typeof chat.with === "object" ? chat.with : null) || {};
      const uname = String(chat.withUsername || chat.with_username || chat.username || partner.username || partner.name || (typeof chat.with === "string" ? chat.with : "") || "").toLowerCase();
      const lm = chat.lastMessage || chat.last_message;
      const preview = lm && typeof lm === "object" ? (lm.text || lm.body || lm.message || "") : (typeof lm === "string" ? lm : "");
      const key = uname || String(chat.chatId || chat.chat_id || chat.id || "");
      if (!key) continue;
      if (this._prevPreview[key] === preview) continue;
      this._prevPreview[key] = preview;
      if (typeof preview !== "string") continue;
      if (preview.indexOf(VC_CALL_PREFIX) !== 0 && preview.indexOf(VC_CALL_DECLINE_PREFIX) !== 0) continue;
      const friend = (ChatStore.getFriends() || []).find(fr => uname && String(fr.username || "").toLowerCase() === uname);
      if (!friend) continue;
      try { await ChatStore.syncChat(friend.id); } catch {}
      this._scanFriendForCall(friend);
    }
  },

  _scanFriendForCall(friend) {
    const msgs = ChatStore.getChat(friend.id) || [];
    const now = Date.now();
    for (let i = msgs.length - 1; i >= 0; i--) {
      const m = msgs[i];
      if (!m || m.deleted || m.from !== "them") continue;
      const parsed = vcParseCall(m.text);
      if (!parsed) continue;
      if (this._handledCallIds.has(m.id)) return;
      this._handledCallIds.add(m.id);
      if (this._handledCallIds.size > 300) {
        this._handledCallIds = new Set(Array.from(this._handledCallIds).slice(-150));
      }
      const age = now - (m.ts || 0);
      if (age > 60000) return;
      if (parsed.kind === "decline") {
        if (this.state === "outgoing" && this.friend && this.friend.id === friend.id) {
          toast("Anruf abgelehnt.");
          this._reset();
        }
      } else if (parsed.kind === "call") {
        this._onIncoming(friend, parsed.data);
      }
      return;
    }
  }
};

