// Live-ZÃ¤hler in der Kopfzeile: wie viele gerade online sind, spielen oder laden.
(function crowdLeiste() {
  const btn = document.getElementById("crowdBtn");
  const pop = document.getElementById("crowdPop");
  const zahl = document.getElementById("crowdCount");
  if (!btn || !pop || !zahl) return;

  function zeile(label, n) {
    return "<div class=\"crowd-row\"><span>" + label + "</span><b>" + n + "</b></div>";
  }
  function liste(titel, arr) {
    if (!arr || !arr.length) return "";
    const zeilen = arr.slice(0, 6).map(function (e) {
      const name = String(e.title || "Spiel").replace(/[&<>"]/g, function (c) {
        return { "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;" }[c];
      });
      return "<div>" + name + (e.count > 1 ? " Â· " + e.count : "") + "</div>";
    }).join("");
    return "<div class=\"crowd-sub\"><b>" + titel + "</b>" + zeilen + "</div>";
  }

  async function laden() {
    if (!api || typeof api.socialApi !== "function") return;
    let res = null;
    try {
      res = await api.socialApi("GET", "/removed");
    } catch (e) {
      res = null;
    }
    const d = res && res.ok && res.data;
    if (!d || d.ok === false) {
      zahl.textContent = "â€“";
      pop.innerHTML = "<h3>Gerade aktiv</h3><div class=\"crowd-sub crowd-err\">Server gerade nicht erreichbar.</div>";
      return;
    }
    const online = Number(d.online) || 0;
    const playing = Number(d.playing) || 0;
    const downloading = Number(d.downloading) || 0;
    zahl.textContent = String(online);
    btn.title = online + " online Â· " + playing + " spielen Â· " + downloading + " laden";
    pop.innerHTML = "<h3>Gerade aktiv</h3>"
      + zeile("Online", online)
      + zeile("Spielen", playing)
      + zeile("Laden herunter", downloading)
      + liste("Spielt gerade", d.playingNow)
      + liste("LÃ¤dt gerade", d.downloadingNow);
  }

  btn.addEventListener("click", function (ev) {
    ev.stopPropagation();
    const auf = pop.hidden;
    pop.hidden = !auf;
    if (auf) laden();
  });
  document.addEventListener("click", function (ev) {
    if (pop.hidden) return;
    if (ev.target === pop || pop.contains(ev.target) || ev.target === btn) return;
    pop.hidden = true;
  });
  laden();
  setInterval(laden, 20000);
})();

// Fensterknoepfe der eigenen Titelleiste
(function () {
  if (typeof api === "undefined" || !api || typeof api.windowControl !== "function") return;
  const maxBtn = document.getElementById("winMaxBtn");
  const MAX_SVG = "<svg viewBox=\"0 0 10 10\"><rect x=\"0.5\" y=\"0.5\" width=\"9\" height=\"9\" /></svg>";
  const ZURUECK_SVG = "<svg viewBox=\"0 0 10 10\"><rect x=\"0.5\" y=\"2.5\" width=\"7\" height=\"7\" /><path d=\"M2.5 2.5V0.5h7v7h-2\" /></svg>";
  const zeigeMax = function (max) {
    if (!maxBtn) return;
    maxBtn.innerHTML = max ? ZURUECK_SVG : MAX_SVG;
    maxBtn.title = max ? "Verkleinern" : "Maximieren";
  };
  [["winMinBtn", "minimize"], ["winMaxBtn", "maximize"], ["winCloseBtn", "close"]].forEach(function (paar) {
    const b = document.getElementById(paar[0]);
    if (b) b.addEventListener("click", function () {
      api.windowControl(paar[1]).then(function (r) {
        if (r && paar[1] === "maximize") zeigeMax(r.maximized);
      }).catch(function () {});
    });
  });
  if (typeof api.onWindowMaximized === "function") api.onWindowMaximized(zeigeMax);
})();

// Kein Kopieren von Text oder Bildern aus der Oberflaeche. In Such- und
// Eingabefeldern bleibt Einfuegen und Markieren, damit man weiter tippen kann.
(function () {
  const istFeld = function (el) {
    if (!el) return false;
    const t = String(el.tagName || "").toLowerCase();
    return t === "input" || t === "textarea" || el.isContentEditable === true;
  };
  document.addEventListener("copy", function (ev) {
    if (istFeld(ev.target)) return;
    ev.preventDefault();
  });
  document.addEventListener("cut", function (ev) {
    if (istFeld(ev.target)) return;
    ev.preventDefault();
  });
  document.addEventListener("contextmenu", function (ev) {
    if (istFeld(ev.target)) return;
    ev.preventDefault();
  });
  document.addEventListener("dragstart", function (ev) {
    const z = ev.target;
    if (z && (z.tagName === "IMG" || z.tagName === "VIDEO" || (z.closest && z.closest("img,video")))) {
      ev.preventDefault();
    }
  });
  document.addEventListener("keydown", function (ev) {
    const k = String(ev.key || "").toLowerCase();
    if (!(ev.ctrlKey || ev.metaKey)) return;
    if (k === "c" || k === "x") {
      if (istFeld(ev.target)) return;
      ev.preventDefault();
    }
  });
})();
